import unittest

from solution import bundle_order


class BundleOrderTests(unittest.TestCase):
    def test_dependency_before_dependent_order(self):
        graph = {
            "app": ["ui", "core"],
            "ui": ["shared"],
            "core": ["shared", "db"],
            "shared": [],
            "db": [],
        }
        self.assertEqual(bundle_order(graph, "app"), ["shared", "ui", "db", "core", "app"])

    def test_unreachable_components_are_ignored_in_result(self):
        graph = {"entry": ["dep"], "dep": [], "unused": ["dep"]}
        self.assertEqual(bundle_order(graph, "entry"), ["dep", "entry"])
        self.assertEqual(bundle_order({"solo": []}, "solo"), ["solo"])

    def test_shared_dependency_position_comes_from_first_visit(self):
        graph = {
            "root": ["left", "right"],
            "left": ["shared"],
            "right": ["shared"],
            "shared": [],
        }
        self.assertEqual(bundle_order(graph, "root"), ["shared", "left", "right", "root"])

    def test_reachable_cycles_raise_value_error(self):
        for graph in (
            {"a": ["a"]},
            {"a": ["b"], "b": ["c"], "c": ["a"]},
        ):
            with self.subTest(graph=graph):
                with self.assertRaises(ValueError):
                    bundle_order(graph, "a")

    def test_unreachable_cycle_does_not_affect_traversal(self):
        graph = {"entry": [], "x": ["y"], "y": ["x"]}
        self.assertEqual(bundle_order(graph, "entry"), ["entry"])

    def test_invalid_graph_entry_and_structural_types(self):
        for graph in (None, [], (), "graph"):
            with self.subTest(graph=graph):
                with self.assertRaises(TypeError):
                    bundle_order(graph, "a")
        for entry in (None, 1, True):
            with self.subTest(entry=entry):
                with self.assertRaises(TypeError):
                    bundle_order({}, entry)
        with self.assertRaises(ValueError):
            bundle_order({}, "")
        with self.assertRaises(KeyError):
            bundle_order({}, "missing")

    def test_invalid_names_and_dependency_containers(self):
        with self.assertRaises(TypeError):
            bundle_order({1: []}, "entry")
        with self.assertRaises(ValueError):
            bundle_order({"": []}, "entry")
        for dependencies in (None, {}, "dep", iter([])):
            with self.subTest(dependencies=dependencies):
                with self.assertRaises(TypeError):
                    bundle_order({"entry": dependencies}, "entry")
        with self.assertRaises(TypeError):
            bundle_order({"entry": [1]}, "entry")
        with self.assertRaises(ValueError):
            bundle_order({"entry": [""]}, "entry")

    def test_entire_graph_references_are_validated_before_traversal(self):
        with self.assertRaises(KeyError):
            bundle_order({"entry": [], "unused": ["missing"]}, "entry")
        with self.assertRaises(KeyError):
            bundle_order({"entry": ["missing"]}, "entry")

    def test_input_is_not_mutated(self):
        graph = {"a": ["b"], "b": []}
        self.assertEqual(bundle_order(graph, "a"), ["b", "a"])
        self.assertEqual(graph, {"a": ["b"], "b": []})


if __name__ == "__main__":
    unittest.main()

